Here is the commit message:
riscv: Fix arch_hugetlb_migration_supported() for NAPOT

arch_hugetlb_migration_supported() must be reimplemented to add support
for NAPOT hugepages, which is done here.

Fixes: 82a1a1f3bfb6 ("riscv: mm: support Svnapot in hugetlb page")
Signed-off-by: Alexandre Ghiti <alexghiti@rivosinc.com>
Link: https://lore.kernel.org/r/20240130120114.106003-1-alexghiti@rivosinc.com
Signed-off-by: Palmer Dabbelt <palmer@rivosinc.com>

Here is the root cause:
The function `arch_hugetlb_migration_supported()` was not properly implemented to handle NAPOT (Naturally Aligned Power Of Two) hugepages, which led to incorrect behavior when checking for migration support of these pages. The lack of this implementation meant that the system could not accurately determine if migration of NAPOT hugepages was supported, potentially causing issues in memory management and allocation.

Here is the patch:

-static __init bool is_napot_size(unsigned long size)
+static bool is_napot_size(unsigned long size)
 {
 	unsigned long order;

 	if (!has_svnapot())
 		return false;

 	for_each_napot_order(order) {
 		if (size == napot_cont_size(order))
 			return true;
 	}
 	return false;
 }


-static __init bool is_napot_size(unsigned long size)
+static bool is_napot_size(unsigned long size)
 {
 	return false;
 }


-bool __init arch_hugetlb_valid_size(unsigned long size)
+static bool __hugetlb_valid_size(unsigned long size)
 {
 	if (size == HPAGE_SIZE)
 		return true;
 	else if (IS_ENABLED(CONFIG_64BIT) && size == PUD_SIZE)
 		return true;
 	else if (is_napot_size(size))
 		return true;
 	else
 		return false;
 }

+bool __init arch_hugetlb_valid_size(unsigned long size)
+{
+	return __hugetlb_valid_size(size);
+}
+
+bool arch_hugetlb_migration_supported(struct hstate *h)
+{
+	return __hugetlb_valid_size(huge_page_size(h));
+}
+
 #ifdef CONFIG_CONTIG_ALLOC
 static __init int gigantic_pages_init(void)


